def solve(intervals):
    """Merge overlapping or touching intervals.
    Handles intervals where start may be greater than end by normalizing.
    Returns merged intervals as list of lists sorted by start.
    """
    # Filter out empty intervals and normalize each to [start, end]
    cleaned = []
    for iv in intervals:
        if not iv:
            continue
        # Accept tuple or list of two items
        if len(iv) != 2:
            continue
        a, b = iv[0], iv[1]
        if a <= b:
            cleaned.append([a, b])
        else:
            cleaned.append([b, a])
    if not cleaned:
        return []
    # Sort by start
    cleaned.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = cleaned[0]
    for start, end in cleaned[1:]:
        if start <= cur_end:  # overlap or touch
            if end > cur_end:
                cur_end = end
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

